<?php require __DIR__.'/../includes/app.php';session_start_safe();if(admin())go('admin/panel.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_ok())$error='El formulario venció.';else{$q=db()->prepare('SELECT * FROM administradores WHERE usuario=? AND activo=1 LIMIT 1');$q->execute([strtolower(trim($_POST['usuario']??''))]);$a=$q->fetch();if($a&&password_verify($_POST['clave']??'',$a['clave_hash'])){session_regenerate_id(true);$_SESSION['admin']=['id'=>(int)$a['id'],'nombre'=>$a['nombre'],'usuario'=>$a['usuario']];$_SESSION['last']=time();audit((int)$a['id'],'inicio_sesion','administradores',(int)$a['id']);go('admin/panel.php');}$error='Usuario o contraseña incorrectos.';}}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administración</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;font-family:Arial;background:linear-gradient(135deg,#311447,#6d3991)}.login{width:100%;max-width:430px;background:#fff;padding:32px;border-radius:18px;box-shadow:0 20px 50px #16082055}.logo{width:58px;height:58px;display:grid;place-items:center;background:#eee5f5;color:#5b2b82;border-radius:15px;font-weight:bold;font-size:24px}h1{color:#421d5e;margin-bottom:6px}.field{margin:16px 0}.field label{display:block;font-weight:bold;margin-bottom:6px}.field input{width:100%;padding:13px;border:1px solid #cec5d4;border-radius:9px;font-size:16px}.btn{width:100%;padding:13px;border:0;border-radius:9px;background:#5b2b82;color:#fff;font-weight:bold;font-size:16px}.error{background:#fdeaea;color:#922;padding:12px;border-radius:9px}</style></head><body><main class="login"><div class="logo">BM</div><h1>Panel administrativo</h1><p>Gestiona actividades, turnos, cupos e inscripciones.</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div cla